{
  "name": "argo-probe",
  "version": "0.0.1",
  "description": "Argonauts live check: a mod that adds context, registers commands, and pushes toast, status, and log lines."
}

// Argonauts live check. Every effect carries a marker word,
// so the stream and the model's answer show which hooks ran.
export function register(on) {
  let lateRegistered = false

  on('session.start', async ($, e, next) => {
    $.ui.log('PROBE-LOG-START session.start ran')
    $.ui.toast('PROBE-TOAST-START')
    await $.command.register({
      name: 'probe-cmd',
      description: 'Argonauts probe: answers with a fixed line',
    })
    return next(e)
  })

  // Context added to every turn: a block next to claudeMd and currentDate.
  on('prompt.context', async ($, e, next) =>
    next({
      ...e,
      blocks: [...e.blocks, { name: 'argoProbe', text: 'Probe code word: KESTREL-29.' }],
    }),
  )

  // The prompt as typed, with one more line.
  on('prompt.submit', async ($, e, next) =>
    next({ ...e, text: `${e.text}\n\n(Probe code word: HERON-41.)` }),
  )

  on('command.run', { command: 'probe-cmd' }, async $ => {
    $.ui.toast('PROBE-TOAST-CMD')
    $.ui.status('PROBE-STATUS-CMD')
    $.ui.log('PROBE-LOG-CMD')
    return { text: 'PROBE-CMD-OUTPUT probe-cmd ran' }
  })

  on('command.run', { command: 'probe-late' }, async () => ({ text: 'PROBE-LATE-OUTPUT' }))

  // Registered mid-session, to see whether Claude Code reports commands_changed.
  on('turn.complete', async ($, e, next) => {
    if (!lateRegistered) {
      lateRegistered = true
      await $.command.register({
        name: 'probe-late',
        description: 'Argonauts probe: registered after the first turn',
      })
    }
    return next(e)
  })
}
